def shortest_path(edges, start, end):
    """
    Find the shortest path from start to end in a directed graph with weighted edges.

    Parameters:
        edges (list of tuple): List of (from_node, to_node, weight) tuples
        start (hashable): Starting node
        end (hashable): Ending node

    Returns:
        tuple: (distance, path) where path is a list of nodes from start to end

    Raises:
        ValueError: If any edge has a negative weight
    """
    # Handle the case when start and end are the same
    if start == end:
        return (0, [start])

    # Build adjacency list and validate non-negative weights
    graph = {}
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight not allowed")
        if from_node not in graph:
            graph[from_node] = {}
        graph[from_node][to_node] = weight

    # Initialize distance dictionary and previous node mapping
    dist = {start: 0}
    prev = {}
    pq = [(0, start)]
    visited = set()

    # Dijkstra's algorithm using a min-heap
    import heapq
    while pq:
        d, current = heapq.heappop(pq)

        if current in visited:
            continue
        visited.add(current)

        if current == end:
            break

        if current not in graph:
            continue

        for neighbor, weight in graph[current].items():
            new_dist = d + weight
            if neighbor not in dist or new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                prev[neighbor] = current
                heapq.heappush(pq, (new_dist, neighbor))

    # If end is unreachable
    if end not in dist:
        return (None, None)

    # Reconstruct the path from start to end
    path = []
    current = end
    while current != start:
        path.append(current)
        current = prev.get(current)
        if current is None:
            break  # Should not occur if end is reachable
    path.append(start)
    path.reverse()

    return (dist[end], path)
